/**
 * Technician mileage log (migration 0125) — a manual entry log, PLUS
 * (migration 0128) an optional auto-sync path that derives entries from a
 * technician's completed tickets. Manual entries are typed in directly;
 * auto-synced ones (source: "auto") are generated by syncMileageFromTickets
 * below, reusing the same office-to-customer distance calculator already
 * used on the ticket detail page (mapEngine.ts's computeOfficeDistanceMiles)
 * rather than any new mileage math. Edited on Accounting Dashboard's
 * Mileage tab.
 */

import { supabase } from "./client";
import { getCompanyMapProvider } from "./companySettings";
import { computeOfficeDistanceMiles, type MileageTicketInput } from "@/lib/mapEngine";
import { statusGroupOf } from "@/lib/ticketData";

export interface MileageEntry {
  id: string;
  profileId: string;
  branch: string;
  workDate: string;
  address: string;
  contactNumber: string | null;
  email: string | null;
  totalMileage: number;
  googleMapLink: string | null;
  createdByName: string | null;
  createdAt: string;
  ticketId: string | null;
  source: "manual" | "auto";
}

function mapRow(r: any): MileageEntry {
  return {
    id: r.id,
    profileId: r.profile_id,
    branch: r.branch,
    workDate: r.work_date,
    address: r.address,
    contactNumber: r.contact_number ?? null,
    email: r.email ?? null,
    totalMileage: Number(r.total_mileage) || 0,
    googleMapLink: r.google_map_link ?? null,
    createdByName: r.created_by_name ?? null,
    createdAt: r.created_at,
    ticketId: r.ticket_id ?? null,
    source: r.source === "auto" ? "auto" : "manual",
  };
}

/** All mileage entries for the caller's company (RLS-scoped), newest first. */
export async function getMileageEntries(): Promise<MileageEntry[]> {
  const { data, error } = await supabase
    .from("mileage_entries")
    .select("id, profile_id, branch, work_date, address, contact_number, email, total_mileage, google_map_link, created_by_name, created_at, ticket_id, source")
    .order("work_date", { ascending: false });
  if (error) {
    console.error("getMileageEntries error:", error.message);
    return [];
  }
  return (data ?? []).map(mapRow);
}

export async function addMileageEntry(input: {
  profileId: string;
  branch: string;
  workDate: string;
  address: string;
  contactNumber: string;
  email: string;
  totalMileage: number;
  googleMapLink: string;
  createdByName: string;
}): Promise<void> {
  const { error } = await supabase.from("mileage_entries").insert({
    profile_id: input.profileId,
    branch: input.branch,
    work_date: input.workDate,
    address: input.address,
    contact_number: input.contactNumber || null,
    email: input.email || null,
    total_mileage: input.totalMileage,
    google_map_link: input.googleMapLink || null,
    created_by_name: input.createdByName,
  });
  if (error) throw new Error(error.message);
}

export async function deleteMileageEntry(id: string): Promise<void> {
  const { error } = await supabase.from("mileage_entries").delete().eq("id", id);
  if (error) throw new Error(error.message);
}

export interface MileageSyncResult {
  created: number;
  skipped: number;
  errors: string[];
}

/**
 * Auto-generates mileage entries from a technician's COMPLETED tickets in a
 * date range — one row per ticket (not a combined daily total), each priced
 * with the same office-to-customer distance calculator already used on the
 * ticket detail page. Safe to re-run for an overlapping range: tickets that
 * already produced a row (tracked via mileage_entries.ticket_id, enforced
 * unique by migration 0128) are skipped rather than duplicated.
 *
 * "Completed" is deliberately the exact same definition Overall Status's
 * Tech Completion Rate table uses (overallStatusData.ts's techMap
 * builder) — the ticket's own `technician`/`status` fields run through
 * statusGroupOf, NOT the visit-level repair_status Tech Payroll uses. That
 * keeps this in sync with what the user actually sees as "completed" on
 * that dashboard, rather than a different, visit-level notion of done.
 * Redo tickets are NOT excluded here (unlike Tech Payroll) — a redo still
 * involved a real drive, it's only excluded from pay because that's a
 * piece-rate concern, not a mileage one.
 */
export async function syncMileageFromTickets(input: {
  profileId: string;
  technicianName: string;
  branch: string;
  startDate: string;
  endDate: string;
}): Promise<MileageSyncResult> {
  const result: MileageSyncResult = { created: 0, skipped: 0, errors: [] };
  if (!input.technicianName.trim()) return result;

  const [{ data: ticketRows, error: ticketsErr }, { data: syncedRows, error: syncedErr }, mapProvider] = await Promise.all([
    supabase
      .from("tickets")
      .select("id, ticket_no, technician, status, schedule_date, location, account, customer:customers ( address, address2, city, state, zip, phone, email )")
      .eq("technician", input.technicianName)
      .gte("schedule_date", input.startDate)
      .lte("schedule_date", input.endDate),
    supabase.from("mileage_entries").select("ticket_id").not("ticket_id", "is", null),
    getCompanyMapProvider(),
  ]);
  if (ticketsErr) {
    result.errors.push(`Failed to load tickets: ${ticketsErr.message}`);
    return result;
  }
  if (syncedErr) console.error("syncMileageFromTickets (existing sync check) error:", syncedErr.message);
  const alreadySynced = new Set((syncedRows ?? []).map((r: any) => r.ticket_id));

  const completedTickets = (ticketRows ?? []).filter((t: any) => statusGroupOf(t.status || "") === "completed");
  const pending = completedTickets.filter((t: any) => !alreadySynced.has(t.id));
  result.skipped = completedTickets.length - pending.length;
  if (pending.length === 0) return result;

  for (const ticket of pending as any[]) {
    const customer = ticket.customer ?? {};
    const mileageInput: MileageTicketInput = {
      location: ticket.location,
      city: customer.city,
      address: customer.address,
      state: customer.state,
      zip: customer.zip,
      account: ticket.account,
    };
    let miles: number | null = null;
    try {
      miles = await computeOfficeDistanceMiles(mileageInput, mapProvider);
    } catch (err) {
      result.errors.push(`Ticket ${ticket.ticket_no}: ${err instanceof Error ? err.message : "distance lookup failed"}`);
      continue;
    }
    if (miles === null) {
      result.errors.push(`Ticket ${ticket.ticket_no}: no route found — skipped.`);
      continue;
    }

    const fullAddress = [customer.address, customer.address2, [customer.city, customer.state].filter(Boolean).join(", "), customer.zip]
      .filter((part: unknown) => typeof part === "string" && part.trim())
      .join(", ");
    const googleMapLink = fullAddress
      ? `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(fullAddress)}`
      : "";

    const { error: insertErr } = await supabase.from("mileage_entries").insert({
      profile_id: input.profileId,
      branch: ticket.location || input.branch,
      work_date: ticket.schedule_date,
      address: fullAddress || "(no address on file)",
      contact_number: customer.phone || null,
      email: customer.email || null,
      total_mileage: Math.round(miles * 10) / 10,
      google_map_link: googleMapLink || null,
      created_by_name: "Auto-sync",
      ticket_id: ticket.id,
      source: "auto",
    });
    if (insertErr) {
      // Unique-violation on ticket_id means another sync run already logged
      // it a moment ago (race) — treat as skipped, not a real failure.
      if (insertErr.code === "23505") result.skipped++;
      else result.errors.push(`Ticket ${ticket.ticket_no}: ${insertErr.message}`);
      continue;
    }
    result.created++;
  }

  return result;
}
